export function getBankProfile(inn?: string): BankApplicationProfile | undefined {
  if (!inn) return BANK_APPLICATIONS[0];
  const found = BANK_APPLICATIONS.find(a => a.inn === inn);
  return found || BANK_APPLICATIONS[0];
}

export function getBankFacts(applicationId?: string): BankFact[] {
  const appId = applicationId || 'DEMO-001';
  return BANK_FACTS.filter(f => f.application_id === appId);
}

export function getBankDebts(applicationId?: string): BankDebt[] {
  const appId = applicationId || 'DEMO-001';
  const debts = BANK_DEBTS.filter(d => d.application_id === appId);
  const merged: Record<string, BankDebt> = {};
  for (const d of debts) {
    const prev = merged[d.obligation_ref];
    if (!prev || Number(d.monthly_max_payment_rub) > Number(prev.monthly_max_payment_rub)) {
      merged[d.obligation_ref] = d;
    }
  }
  return Object.values(merged);
}
